{
  "title": "Encrypted archive upload to personal cloud storage",
  "id": "a1b2c3d4-5e6f-7g8h-9i0j-k1l2m3n4o5p6",
  "status": "experimental",
  "description": "Detects compression of large numbers of files into encrypted 7z archives and subsequent upload to personal cloud services such as Dropbox.",
  "author": "SOC Team",
  "logsource": {
    "product": "windows",
    "service": "filemonitor"
  },
  "detection": {
    "selection": {
      "EventID": 4663,
      "ObjectName|endswith": ".7z",
      "ObjectName|contains": "\\Finance\\"
    },
    "encryption": {
      "ProcessName|contains": "7z",
      "CommandLine|contains": ["-p", "-e"]
    },
    "upload": {
      "EventID": 5156,
      "DestinationPort": 443,
      "DestinationHostname|contains": ["dropbox.com", "drive.google.com", "onedrive.com"]
    },
    "filter": {
      "FileCount": {"gte": 500},
      "FileSizeTotal": {"gte": 2000000000}
    },
    "condition": "selection and encryption and upload and filter"
  },
  "fields": ["User", "ObjectName", "ProcessName", "CommandLine", "DestinationHostname", "FileCount", "FileSizeTotal"],
  "falsepositives": ["Legitimate backup processes"],
  "level": "high"
}
